//! Two-apex full-wrap revolution charts (PK-339): a face whose ring
//! nets a full u period THROUGH TWO chart-degenerate points — the
//! classic case is a full sphere (two poles joined by one meridian
//! seam). The ring is [pole run][meridian ladder][pole run][meridian
//! ladder]: no constant-v circle exists, so the mono-apex path cannot
//! serve it. Rows come from the meridian ladder verbatim (the seam
//! chain is chord-refined already — reusing it keeps the face boundary
//! exactly equal to the ring); stations are generated by the
//! azimuthal chord criterion at the widest row.

use popkern_core::geometry::Vec3;
use popkern_core::geometry::surface::{SurfaceEval, SurfaceGeometry};
use popkern_core::topology::FaceHandle;

use std::collections::HashMap;

use super::{BoundaryRing, boundary_first_edge_samples::EdgeSamples};
use crate::TessellationOptions;
use crate::mesh::{FaceMesh, MeshVertex};
use popkern_core::topology::{BRep, EdgeHandle};

fn trace(reason: &str) {
    if std::env::var_os("PK_BF_TRACE").is_some() {
        eprintln!("    [bf] bipolar revolution declined: {reason}");
    }
}

/// Attempt the two-apex structured revolution tessellation.
pub(super) fn try_tessellate(
    face_handle: FaceHandle,
    surface: &SurfaceGeometry,
    orientation: bool,
    ring: &BoundaryRing,
    u_degenerate: &[bool],
    period_u: f64,
    options: &TessellationOptions,
) -> Option<FaceMesh> {
    let n = ring.uv.len();
    if n < 4 || u_degenerate.len() != n {
        return None;
    }
    let scale = ring
        .pos
        .iter()
        .zip(ring.pos.iter().cycle().skip(1))
        .map(|(a, b)| a.distance_to(b))
        .fold(0.0_f64, f64::max)
        .max(1e-9);

    // Two degenerate runs, two non-degenerate ladders, in cyclic
    // alternation.
    let start = (0..n).find(|&i| u_degenerate[i] && !u_degenerate[(i + 1) % n])? + 1;
    let ordered: Vec<usize> = (0..n).map(|k| (start + k) % n).collect();
    let mut blocks: Vec<(bool, Vec<usize>)> = Vec::new();
    for &i in &ordered {
        let d = u_degenerate[i];
        match blocks.last_mut() {
            Some((bd, block)) if *bd == d => block.push(i),
            _ => blocks.push((d, vec![i])),
        }
    }
    if blocks.len() != 4 {
        trace("ring is not ladder/pole/ladder/pole");
        return None;
    }
    let (l1_deg, ladder1) = &blocks[0];
    let (p2_deg, pole2_run) = &blocks[1];
    let (l2_deg, ladder2) = &blocks[2];
    let (p1_deg, pole1_run) = &blocks[3];
    if *l1_deg || *l2_deg || !*p1_deg || !*p2_deg {
        trace("blocks do not alternate ladder/pole");
        return None;
    }
    let pole_point = |run: &[usize]| -> Option<(popkern_core::geometry::Point3, f64)> {
        let p = ring.pos[run[0]];
        if run
            .iter()
            .any(|&i| ring.pos[i].distance_to(&p) > 1e-7 * scale)
        {
            return None;
        }
        let v = run.iter().map(|&i| ring.uv[i].1).sum::<f64>() / run.len() as f64;
        Some((p, v))
    };
    let (pole1, v1) = match pole_point(pole1_run) {
        Some(x) => x,
        None => {
            trace("pole run is not a single point");
            return None;
        }
    };
    let (pole2, v2) = match pole_point(pole2_run) {
        Some(x) => x,
        None => {
            trace("pole run is not a single point");
            return None;
        }
    };

    // Ladders: u-constant (periodic), mirrored v stations, monotone v.
    // ladder1 runs pole1 → pole2, ladder2 runs pole2 → pole1.
    if ladder1.len() != ladder2.len() || ladder1.is_empty() {
        trace("meridian ladders differ in station count");
        return None;
    }
    let eps_u = 1e-6 * period_u;
    let eps_v = 1e-6 * (v2 - v1).abs().max(1e-9);
    let periodic_du = |a: f64, b: f64| {
        let d = (a - b).rem_euclid(period_u);
        d.min(period_u - d)
    };
    let u1 = ring.uv[ladder1[0]].0;
    let u2 = ring.uv[ladder2[0]].0;
    for &i in ladder1 {
        if periodic_du(ring.uv[i].0, u1) > eps_u {
            trace("meridian ladder leaves its seam azimuth");
            return None;
        }
    }
    for &i in ladder2 {
        if periodic_du(ring.uv[i].0, u2) > eps_u {
            trace("meridian ladder leaves its seam azimuth");
            return None;
        }
    }
    if periodic_du(u1, u2) > eps_u {
        trace("the two ladders are not the same seam azimuth");
        return None;
    }
    for (a, b) in ladder1.iter().zip(ladder2.iter().rev()) {
        if (ring.uv[*a].1 - ring.uv[*b].1).abs() > eps_v {
            trace("meridian ladders not mirrored");
            return None;
        }
    }
    let toward_2 = (v2 - v1).signum();
    for w in ladder1.windows(2) {
        if toward_2 * (ring.uv[w[1]].1 - ring.uv[w[0]].1) <= 0.0 {
            trace("meridian ladder v not monotone");
            return None;
        }
    }

    // Rows carry their ladder index when they came from the ring
    // (seam columns adopt those positions verbatim); sag-refinement
    // bisects under-resolved bands with surface evaluations, which
    // agree on both seam sides so welds stay closed.
    let mut rows_v: Vec<(f64, Option<usize>)> = ladder1
        .iter()
        .enumerate()
        .map(|(j, &i)| (ring.uv[i].1, Some(j)))
        .collect();
    {
        let u_probe = ring.uv[ladder1[0]].0;
        let sag = |va: f64, vb: f64| {
            let pa = surface.point_at(u_probe, va);
            let pb = surface.point_at(u_probe, vb);
            let pm = surface.point_at(u_probe, 0.5 * (va + vb));
            let chord_mid = popkern_core::geometry::Point3::new(
                0.5 * (pa.x + pb.x),
                0.5 * (pa.y + pb.y),
                0.5 * (pa.z + pb.z),
            );
            pm.distance_to(&chord_mid)
        };
        for _ in 0..options.max_subdivisions.max(1) {
            let mut refined: Vec<(f64, Option<usize>)> = Vec::with_capacity(rows_v.len() * 2);
            let mut inserted = false;
            let mut prev_v = v1;
            for &(v, src) in &rows_v {
                if sag(prev_v, v) > options.chord_height {
                    refined.push((0.5 * (prev_v + v), None));
                    inserted = true;
                }
                refined.push((v, src));
                prev_v = v;
            }
            if sag(prev_v, v2) > options.chord_height {
                refined.push((0.5 * (prev_v + v2), None));
                inserted = true;
            }
            rows_v = refined;
            if !inserted {
                break;
            }
        }
    }
    // Stations from the azimuthal chord criterion at the widest row.
    let widest_v = rows_v.iter().map(|&(v, _)| v).max_by(|a, b| {
        let r = |v: f64| {
            surface
                .point_at(u1, v)
                .distance_to(&surface.point_at(u1 + 0.5 * period_u, v))
        };
        r(*a).total_cmp(&r(*b))
    })?;
    let mut stations = 8usize;
    while stations < 4096 {
        let du = period_u / stations as f64;
        let pa = surface.point_at(u1, widest_v);
        let pb = surface.point_at(u1 + du, widest_v);
        let pm = surface.point_at(u1 + 0.5 * du, widest_v);
        let chord_mid = popkern_core::geometry::Point3::new(
            0.5 * (pa.x + pb.x),
            0.5 * (pa.y + pb.y),
            0.5 * (pa.z + pb.z),
        );
        if pm.distance_to(&chord_mid) <= options.chord_height {
            break;
        }
        stations *= 2;
    }
    let k = stations + 1; // seam column duplicated at both ends

    let mut uv_pts: Vec<(f64, f64)> = Vec::new();
    let mut vertices: Vec<MeshVertex> = Vec::new();
    let push = |uv_pts: &mut Vec<(f64, f64)>,
                vertices: &mut Vec<MeshVertex>,
                u: f64,
                v: f64,
                pos: Option<popkern_core::geometry::Point3>| {
        let position = pos.unwrap_or_else(|| surface.point_at(u, v));
        let mut normal = surface.normal_at(u, v);
        let len = normal.length();
        if len > 1e-300 {
            normal = Vec3::new(normal.x / len, normal.y / len, normal.z / len);
        }
        if !orientation {
            normal = -normal;
        }
        uv_pts.push((u, v));
        vertices.push(MeshVertex {
            position,
            normal,
            uv: (u, v),
        });
    };

    // pole1 vertex, ladder rows, pole2 vertex.
    push(
        &mut uv_pts,
        &mut vertices,
        u1 + 0.5 * period_u,
        v1 + (v2 - v1) * 1e-6,
        Some(pole1),
    );
    for &(v, src) in &rows_v {
        for s in 0..k {
            let u = u1 + period_u * s as f64 / stations as f64;
            let seam_pos = match src {
                Some(j) if s == 0 => Some(ring.pos[ladder1[j]]),
                Some(j) if s == stations => Some(ring.pos[ladder2[ladder2.len() - 1 - j]]),
                _ => None,
            };
            push(&mut uv_pts, &mut vertices, u, v, seam_pos);
        }
    }
    let pole2_idx = vertices.len();
    push(
        &mut uv_pts,
        &mut vertices,
        u1 + 0.5 * period_u,
        v2 - (v2 - v1) * 1e-6,
        Some(pole2),
    );

    let row_at = |j: usize, s: usize| -> usize { 1 + j * k + s };
    let mut triangles: Vec<[usize; 3]> = Vec::new();
    for s in 0..stations {
        triangles.push([0, row_at(0, s), row_at(0, s + 1)]);
    }
    for j in 0..rows_v.len() - 1 {
        for s in 0..stations {
            let (p00, p10, p11, p01) = (
                row_at(j, s),
                row_at(j, s + 1),
                row_at(j + 1, s + 1),
                row_at(j + 1, s),
            );
            triangles.push([p00, p10, p11]);
            triangles.push([p00, p11, p01]);
        }
    }
    let last = rows_v.len() - 1;
    for s in 0..stations {
        triangles.push([pole2_idx, row_at(last, s + 1), row_at(last, s)]);
    }

    // Positive UV winding, then the stored orientation flag.
    for t in &mut triangles {
        let (a, b, c) = (uv_pts[t[0]], uv_pts[t[1]], uv_pts[t[2]]);
        let signed = (b.0 - a.0) * (c.1 - a.1) - (c.0 - a.0) * (b.1 - a.1);
        if signed < 0.0 {
            t.swap(1, 2);
        }
    }
    if !orientation {
        for t in &mut triangles {
            t.swap(1, 2);
        }
    }
    if std::env::var_os("PK_BF_TRACE").is_some() {
        eprintln!(
            "    [bf] face {face_handle:?} served as bipolar revolution: {stations} stations x {} rows",
            rows_v.len()
        );
    }
    Some(FaceMesh {
        face: face_handle,
        vertices,
        triangles,
    })
}

/// A pure seam-spine face (every outer-loop edge traversed twice):
/// build its ring and attempt ONLY the revolution paths — Delaunay
/// cannot chart two overlapping border lines. `None` keeps the legacy
/// pcurve-grid fallback.
pub(super) fn seam_spine_revolution(
    brep: &BRep,
    face_handle: FaceHandle,
    edge_samples: &HashMap<EdgeHandle, EdgeSamples>,
    options: &TessellationOptions,
) -> Option<FaceMesh> {
    use popkern_core::geometry::surface::SurfaceEval as _;
    let face = brep.faces.get(face_handle)?;
    let surface_on_face = face.surface.as_ref()?;
    let surface = &surface_on_face.geometry;
    let orientation = surface_on_face.orientation;
    if !face.inner_loops.is_empty() {
        return None;
    }
    let (period_u, _) = surface.parameter_periodicity();
    let p = period_u?;
    let ring = super::build_ring(brep, face.outer_loop, edge_samples)?;
    let ring_scale = ring
        .pos
        .iter()
        .zip(ring.pos.iter().cycle().skip(1))
        .map(|(a, b)| a.distance_to(b))
        .fold(0.0_f64, f64::max)
        .max(1e-9);
    let u_degenerate: Vec<bool> = ring
        .uv
        .iter()
        .zip(ring.pos.iter())
        .map(|((u, v), pos)| {
            surface.point_at(u + 0.5 * p, *v).distance_to(pos) < 1.0e-4 * ring_scale
        })
        .collect();
    super::boundary_first_revolution::try_tessellate(
        face_handle,
        surface,
        orientation,
        &ring,
        &u_degenerate,
        p,
        options,
    )
}
